insert into public.places
  (name, category, place_type, city, address, latitude, longitude, slug,
   short_description, long_description, source_url, external_source, external_id,
   verified, trust_score, is_active, content_review_status, tags)
select v.name, v.category, v.place_type, 'Mersin', v.address, v.lat, v.lon,
       v.slug, v.short_description, v.long_description, v.source_url,
       'curated_seed', 'mersin-' || v.slug, false, 85, true, 'source_backed',
       v.tags::jsonb
from (values
('Kızkalesi','Tarih ve arkeoloji','Kıyı kalesi','Kızkalesi, Erdemli, Mersin',36.4613::float8,34.1448::float8,'kizkalesi','Deniz içindeki küçük adada yükselen tarihî kale','Korykos kıyı yerleşiminin simgelerinden Kızkalesi, kıyıdan açıkta bulunan ada üzerindeki Orta Çağ kalesidir.','https://mersin.gov.tr/kultur-turizm','["kale","kıyı","tarih"]'),
('Cennet ve Cehennem Obrukları','Doğa','Karstik obruklar','Narlıkuyu, Silifke, Mersin',36.4528::float8,34.1087::float8,'cennet-cehennem-obruklari','Birbirine yakın iki büyük karstik çöküntü','Cennet ve Cehennem, karstik süreçlerle oluşmuş büyük doğal çöküntülerdir; çevresindeki tarihî yapılarla birlikte ziyaret edilir.','https://mersin.gov.tr/kultur-turizm','["jeoloji","doğa","silifke"]'),
('Uzuncaburç Antik Kenti','Tarih ve arkeoloji','Antik kent','Uzuncaburç, Silifke, Mersin',36.5846::float8,33.9493::float8,'uzuncaburc-antik-kenti','Sütunlu caddesi ve anıtsal yapılarıyla öne çıkan antik kent','Diocaesarea adıyla da bilinen Uzuncaburç, tapınak, sütunlu cadde ve anıtsal kapı kalıntılarıyla bölgenin önemli arkeolojik alanlarındandır.','https://mersin.gov.tr/kultur-turizm','["antik kent","arkeoloji","silifke"]'),
('Kanlıdivane Antik Kenti','Tarih ve arkeoloji','Antik kent','Kanlıdivane, Erdemli, Mersin',36.5057::float8,34.1725::float8,'kanlidivane-antik-kenti','Büyük doğal obruk çevresine kurulmuş antik yerleşim','Kanlıdivane, doğal obruk çevresindeki kaya mezarları, kabartmalar ve antik yapı kalıntılarıyla tanınır.','https://mersin.gov.tr/kultur-turizm','["antik kent","obruk","arkeoloji"]'),
('Gilindire (Aynalıgöl) Mağarası','Doğa','Mağara','Aydıncık, Mersin',36.1430::float8,33.3220::float8,'gilindire-aynali-gol-magarasi','Yer altı gölü ve damlataş oluşumlarıyla bilinen mağara','Gilindire Mağarası, sarkıt, dikit ve mağara içindeki gölüyle öne çıkan doğal oluşumdur; erişim koşulları önceden kontrol edilmelidir.','https://mersin.gov.tr/kultur-turizm','["mağara","jeoloji","aydıncık"]'),
('St. Paul Kuyusu','Tarih ve inanç','Tarihî kuyu','Tarsus merkez, Mersin',36.9179::float8,34.8925::float8,'st-paul-kuyusu','Tarsus’un inanç turizmi duraklarından biri','St. Paul Kuyusu, Tarsus’un tarihî merkezindeki St. Paul ile ilişkilendirilen geleneksel ziyaret noktalarındandır.','https://mersin.gov.tr/kultur-turizm','["inanç turizmi","tarsus","tarih"]'),
('Tarsus Şelalesi','Doğa','Şelale','Tarsus, Mersin',36.9428::float8,34.8717::float8,'tarsus-selalesi','Berdan Nehri üzerinde şehir yakınındaki şelale','Tarsus Şelalesi, Berdan Nehri’nin oluşturduğu ve özellikle su debisinin arttığı dönemlerde dikkat çeken doğal duraklardan biridir.','https://mersin.gov.tr/kultur-turizm','["şelale","doğa","tarsus"]'),
('Soli Pompeipolis Antik Kenti','Tarih ve arkeoloji','Antik kent','Viranşehir, Mezitli, Mersin',36.7476::float8,34.5382::float8,'soli-pompeipolis-antik-kenti','Sütunlu caddesiyle bilinen antik liman kenti','Soli Pompeipolis, antik liman kenti kimliği ve günümüze ulaşan sütunlu cadde kalıntılarıyla Mersin’in önemli arkeolojik alanlarındandır.','https://mersin.gov.tr/kultur-turizm','["antik kent","arkeoloji","mezitli"]'),
('Anemurium Antik Kenti','Tarih ve arkeoloji','Antik kent','Anamur, Mersin',36.0244::float8,32.8078::float8,'anemurium-antik-kenti','Akdeniz kıyısında geniş kalıntı alanına sahip antik kent','Anemurium’da nekropol, hamam, tiyatro ve konut kalıntıları gibi farklı dönemlerden yapılar bulunur.','https://mersin.gov.tr/kultur-turizm','["antik kent","arkeoloji","anamur"]'),
('Alahan Manastırı','Tarih ve mimari','Manastır kompleksi','Geçimli, Mut, Mersin',36.7750::float8,33.3070::float8,'alahan-manastiri','Dağ yamacında erken Hristiyanlık dönemi mimari mirası','Alahan Manastırı, anıtsal kilise kalıntıları ve taş işçiliğiyle öne çıkan önemli bir tarihî komplekstir.','https://mersin.gov.tr/kultur-turizm','["manastır","mimari","mut"]'),
('Mamure Kalesi','Tarih ve mimari','Kale','Anamur, Mersin',36.0754::float8,32.8918::float8,'mamure-kalesi','Kıyı şeridinde geniş surlarıyla korunan kale','Mamure Kalesi, Akdeniz kıyısındaki konumu, surları ve kuleleriyle Mersin’in dikkat çeken tarihî yapılarındandır.','https://mersin.gov.tr/kultur-turizm','["kale","tarih","anamur"]'),
('Eshab-ı Kehf Mağarası ve Külliyesi','Tarih ve inanç','Mağara ve külliye','Tarsus, Mersin',37.0160::float8,34.9000::float8,'eshab-i-kehf-magarasi-kulliyesi','Tarsus çevresinde önemli inanç ziyaret alanı','Eshab-ı Kehf, mağara ve çevresindeki dinî yapılarla farklı inanç geleneklerinde önem taşıyan bir ziyaret alanıdır.','https://mersin.gov.tr/kultur-turizm','["inanç turizmi","mağara","tarsus"]'),
('Aya Tekla (Meryemlik) Örenyeri','Tarih ve inanç','Erken Hristiyanlık alanı','Taşucu yolu, Silifke, Mersin',36.3150::float8,33.8910::float8,'aya-tekla-meryemlik-orenyeri','Erken Hristiyanlık dönemine ait kutsal alan','Aya Tekla, mağara-kilise yapısı ve tarihî kalıntılarıyla Silifke çevresinin önemli inanç turizmi noktalarındandır.','https://mersin.gov.tr/kultur-turizm','["inanç turizmi","arkeoloji","silifke"]'),
('Mersin Arkeoloji Müzesi','Müze','Arkeoloji müzesi','Yenişehir, Mersin',36.8010::float8,34.6260::float8,'mersin-arkeoloji-muzesi','Bölgenin arkeolojik geçmişini tanıtan müze','Müze, Mersin ve çevresindeki tarih öncesi dönemlerden antik çağlara uzanan kültürel mirası tanıtan eserleri bir araya getirir.','https://mersin.gov.tr/kultur-turizm','["müze","arkeoloji","mersin"]'),
('Mersin Deniz Müzesi','Müze','Denizcilik müzesi','Yenişehir, Mersin',36.7890::float8,34.6060::float8,'mersin-deniz-muzesi','Denizcilik ve deniz kuvvetleri tarihine odaklanan müze','Mersin Deniz Müzesi, denizcilik tarihine ilişkin sergileri ve koleksiyonlarıyla şehirdeki kültür duraklarından biridir.','https://mersin.gov.tr/kultur-turizm','["müze","denizcilik","mersin"]'),
('Yumuktepe Höyüğü','Tarih ve arkeoloji','Höyük','Demirtaş, Toroslar, Mersin',36.7930::float8,34.5680::float8,'yumuktepe-hoyugu','Çok eski yerleşim katmanlarıyla bilinen arkeolojik höyük','Yumuktepe, Mersin’in tarih öncesi yerleşim geçmişini anlamak açısından önemli bir arkeolojik alandır; ziyaret erişimi önceden doğrulanmalıdır.','https://mersin.gov.tr/kultur-turizm','["höyük","tarih öncesi","arkeoloji"]'),
('Kleopatra Kapısı','Tarih ve mimari','Tarihî kent kapısı','Tarsus merkez, Mersin',36.9170::float8,34.8940::float8,'kleopatra-kapisi','Tarsus’un tarihî kent dokusundan kalan kapı','Kleopatra Kapısı, Tarsus’un tarihî merkezinde bulunan ve kent tarihine ilişkin anlatılarla anılan anıtsal kapıdır.','https://mersin.gov.tr/kultur-turizm','["tarih","mimari","tarsus"]'),
('Nusrat Mayın Gemisi ve Çanakkale Parkı','Müze ve tarih','Tarihî gemi','Tarsus Caddesi, Mersin',36.9180::float8,34.8910::float8,'nusrat-mayin-gemisi','Çanakkale Deniz Savaşları tarihini anlatan gemi müzesi','Nusrat Mayın Gemisi, Çanakkale Deniz Savaşları’yla ilişkilendirilen tarihî geminin sergilendiği ziyaret noktasıdır.','https://mersin.gov.tr/kultur-turizm','["tarih","müze","nusrat"]'),
('Göksu Deltası Kuş Cenneti','Doğa','Sulak alan ve kuş gözlem alanı','Silifke, Mersin',36.3130::float8,33.9500::float8,'goksu-deltasi-kus-cenneti','Göçmen kuşlar ve sulak alan ekosistemiyle önemli doğal alan','Göksu Deltası, kuş çeşitliliği ve sulak alan yaşamı açısından değerlidir; hassas habitatlarda gözlem kurallarına uyulmalıdır.','https://mersin.gov.tr/kultur-turizm','["sulak alan","kuş gözlemi","doğa"]'),
('Tarsus Müzesi','Müze','Kent ve arkeoloji müzesi','Tarsus, Mersin',36.9170::float8,34.8930::float8,'tarsus-muzesi','Tarsus ve çevresinin tarihini anlatan müze','Tarsus Müzesi, bölgenin arkeolojik ve kültürel mirasını tanıtan eserleriyle tarihî kent gezisinin tamamlayıcı duraklarındandır.','https://mersin.gov.tr/kultur-turizm','["müze","tarih","tarsus"]'),
('Silifke Kalesi','Tarih ve mimari','Kale','Silifke merkez, Mersin',36.3770::float8,33.9290::float8,'silifke-kalesi','Şehre hâkim konumdaki tarihî kale','Silifke Kalesi, kentin üst kesimindeki konumuyla çevreyi gören ve bölgenin savunma tarihini yansıtan yapılardandır.','https://mersin.gov.tr/kultur-turizm','["kale","tarih","silifke"]'),
('Tarsus Ulu Camii','Tarih ve mimari','Tarihî cami','Tarsus merkez, Mersin',36.9170::float8,34.8935::float8,'tarsus-ulu-camii','Tarsus tarihî merkezindeki önemli dinî yapı','Tarsus Ulu Camii, tarihî kent merkezinin önemli mimari ve kültürel yapılarından biridir.','https://mersin.gov.tr/kultur-turizm','["cami","mimari","tarsus"]'),
('Taşkuyu Mağarası','Doğa','Mağara','Taşkuyu, Tarsus, Mersin',36.9820::float8,34.8750::float8,'taskuyu-magarasi','Damlataş oluşumlarıyla bilinen doğal mağara','Taşkuyu Mağarası, damlataş oluşumlarıyla öne çıkan doğal ziyaret noktalarındandır; güncel ziyaret ve erişim koşulları ayrıca kontrol edilmelidir.','https://mersin.gov.tr/kultur-turizm','["mağara","jeoloji","tarsus"]')
) as v(name,category,place_type,address,lat,lon,slug,short_description,long_description,source_url,tags)
where not exists (
  select 1
  from public.places p
  where lower(trim(p.city)) = 'mersin'
    and (lower(trim(p.name)) = lower(trim(v.name)) or p.slug = trim(v.slug))
);
